func TestDefaultApiClient_RefusesBodyReplayOnHttpsToHttpDowngrade(t *testing.T) {
	t.Parallel()
	plainServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	}))
	defer plainServer.Close()

	tlsServer := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", plainServer.URL+"/leaked")
		w.WriteHeader(307)
	}))
	defer tlsServer.Close()

	transport := petstore.NewTransportOptionsBuilder().
		VerifySSL(false).
		FollowRedirects(true).
		Build()
	client := petstore.NewDefaultApiClient(transport)
	_, err := client.SendRequest(
		"POST", tlsServer.URL+"/issue",
		map[string]string{"Content-Type": "application/x-www-form-urlencoded"},
		[]byte("client_secret=hunter2"),
	)
	if err == nil {
		t.Fatal("expected error refusing HTTPS→HTTP body replay, got nil")
	}
	if !strings.Contains(err.Error(), "HTTPS") || !strings.Contains(err.Error(), "HTTP") {
		t.Errorf("expected downgrade refusal message, got %q", err.Error())
	}
}

// Gap 3.4: when a 303 forces the follow-up to GET and clears the body,
// the outbound request must also drop the Content-Length header so it
// reflects the now-empty body. Stale Content-Length on a GET trips some
// origins / proxies and is undefined per RFC 7231 §3.3.2.
func TestDefaultApiClient_Drops303ContentLengthOnCoercedGet(t *testing.T) {
	t.Parallel()
	var sawContentLengthOnGet string
	var sawMethodOnFollowup string
	mux := http.NewServeMux()
	mux.HandleFunc("/post", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", "/followup")
		w.WriteHeader(303)
	})
	mux.HandleFunc("/followup", func(w http.ResponseWriter, r *http.Request) {
		sawMethodOnFollowup = r.Method
		sawContentLengthOnGet = r.Header.Get("Content-Length")
		w.WriteHeader(200)
	})
	server := httptest.NewServer(mux)
	defer server.Close()

	transport := petstore.NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	client := petstore.NewDefaultApiClient(transport)
	_, err := client.SendRequest(
		"POST", server.URL+"/post",
		map[string]string{"Content-Type": "application/json"},
		[]byte(`{"hello":"world"}`),
	)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if sawMethodOnFollowup != "GET" {
		t.Errorf("expected GET on 303 follow-up, got %q", sawMethodOnFollowup)
	}
	if sawContentLengthOnGet != "" && sawContentLengthOnGet != "0" {
		t.Errorf("expected Content-Length to be dropped (or 0) on 303 follow-up, got %q",
			sawContentLengthOnGet)
	}
}

// Gap 3.1: an API-key header name harvested from the OpenAPI spec must be
// stripped from a cross-origin 3xx redirect alongside the static sensitive
// allowlist (Authorization, Cookie, Proxy-Authorization). When the spec
// declares no API-key headers the dynamic portion of the allowlist is
// empty and only the static names are present; the static names are
// always stripped regardless of spec content.
func TestDefaultApiClient_StripsAuthorizationAcrossCrossOriginRedirect(t *testing.T) {
	t.Parallel()
	var receivedAuth string
	target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		receivedAuth = r.Header.Get("Authorization")
		w.WriteHeader(200)
	}))
	defer target.Close()

	origin := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", target.URL+"/followed")
		w.WriteHeader(302)
	}))
	defer origin.Close()

	transport := petstore.NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	client := petstore.NewDefaultApiClient(transport)
	_, err := client.SendRequest("GET", origin.URL+"/start",
		map[string]string{"Authorization": "Bearer leaked-token"}, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if receivedAuth != "" {
		t.Errorf("expected Authorization to be stripped across cross-origin redirect, got %q",
			receivedAuth)
	}
}

// close-lifecycle-three-way: sending a request after Close() must fail with the
// uniform SDK error type, not silently succeed or leak a foreign library error.
func TestDefaultApiClient_UseAfterCloseReturnsApiError(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	}))
	defer server.Close()

	client := petstore.NewDefaultApiClient(nil)
	if err := client.Close(); err != nil {
		t.Fatalf("Close returned error: %v", err)
	}

	_, err := client.SendRequest("GET", server.URL+"/test", map[string]string{}, nil)
	if err == nil {
		t.Fatal("expected an error when sending a request after Close()")
	}
	var apiErr *pkgerrors.ApiError
	if !errors.As(err, &apiErr) {
		t.Fatalf("expected use-after-close to return *ApiError, got %T: %v", err, err)
	}
	if !strings.Contains(strings.ToLower(apiErr.Msg), "closed") {
		t.Errorf("expected error message to mention the client is closed, got %q", apiErr.Msg)
	}
}

// response-body-read-error-not-wrapped: a body-read/decompression failure that
// occurs AFTER headers are received must be wrapped in the uniform ApiError
// (StatusCode 0, underlying error preserved on .Cause), matching send-phase
// failures — not surfaced as a bare error.
func TestDefaultApiClient_BodyReadErrorWrappedInApiError(t *testing.T) {
	t.Parallel()
	// Advertise gzip but send bytes that are not valid gzip, so the body-read
	// (decompression) step fails after the 200 headers are received.
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Encoding", "gzip")
		w.WriteHeader(200)
		_, _ = w.Write([]byte("this is not gzip-compressed data"))
	}))
	defer server.Close()

	client := petstore.NewDefaultApiClient(nil)
	_, err := client.SendRequest("GET", server.URL+"/test", map[string]string{}, nil)
	if err == nil {
		t.Fatal("expected an error when the response body cannot be decompressed")
	}
	var apiErr *pkgerrors.ApiError
	if !errors.As(err, &apiErr) {
		t.Fatalf("expected body-read failure to be wrapped in *ApiError, got %T: %v", err, err)
	}
	if apiErr.StatusCode != 0 {
		t.Errorf("expected StatusCode 0 for a body-read failure, got %d", apiErr.StatusCode)
	}
	if apiErr.Cause == nil {
		t.Error("expected the underlying decompression error to be preserved on .Cause")
	}
}

// ca-cert-fail-fast: an explicitly configured CA certificate path that cannot
// be read or parsed must fail fast at construction rather than silently
// falling back to the system trust store (security theater). The Go client
// panics when buildHTTPClient cannot load the cert.
func TestDefaultApiClient_NonexistentCaCertPathFailsFast(t *testing.T) {
	t.Parallel()
	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected a panic when constructing with a non-existent caCertPath")
		}
	}()

	transport := petstore.NewTransportOptionsBuilder().
		CACertPath("/nonexistent/ca.pem").
		Build()
	_ = petstore.NewDefaultApiClient(transport)
}
